var PS_BUILD={cleanplan:{primary:{n:'craa5_cleanplanname',len:100,label:'Clean Plan Name'},prompt:'Create a table named "Clean Plan" (schema name craa5_cleanplan / craa5__p_cleanplan), Organization ownership. Primary column "Clean Plan Name" craa5_cleanplanname (single line of text, 100). Columns: "Plan Key" craa5_plankey (text 200); "Row Type" craa5_rowtype (text 20); "Line Key" craa5_linekey (text 100); "Start" craa5_start (date and time); "End" craa5_end (date and time); "Day" craa5_day (text 10); "Clean Kind" craa5_cleankind (text 50); "Minutes" craa5_minutes (whole number); "Status" craa5_status (text 20); "Details" craa5_details (multiple lines of text, maximum 1,048,576); "Reason" craa5_reason (multiple lines of text, 2000); "Content Hash" craa5_contenthash (text 20); "Area" craa5_area (text 100); "Line" craa5_line (whole number); "MSS Area GUID" craa5_mssareaguid (text 100); "Publish Batch" craa5_publishbatch (text 200). None required. No lookup or choice columns.'},inbox:{primary:{n:'craa5_title',len:200,label:'Title'},prompt:'Create a table named "Schedule Change" (schema name craa5_schedulechange / craa5__p_schedulechange), Organization ownership. Primary column "Title" craa5_title (single line of text, 200). Columns: "Form JSON" craa5_formjson (multiple lines of text, maximum 1,048,576); "Status" craa5_status (text 50); "Result" craa5_result (multiple lines of text, 2000); "Sender" craa5_sender (text 200). None required. No lookup or choice columns. Only needed if change requests arrive by email.'},runs:{only:[F_CLEAN_OV],prompt:'Add one column to the Production Schedule table (craa5__aa_prd_schd / craa5__p_prodschedule): "Clean Override", schema name craa5_cleanoverride, single line of text, maximum length 200, not required. It holds the scheduling department\'s approved change to the clean after a run, as text like "skip|Name|reason" or "midweek|Name|reason". Do not make it a lookup or a choice column.'}};function psColType(t){t=String(t||'');var m=/([0-9][0-9,]*)\)?\s*$/.exec(t.replace(/\)+$/,')')),len=m?Number(m[1].replace(/,/g,'')):undefined;if(/^Single line of text/i.test(t))return{type:'text',len:len||100};if(/^Multiple lines of text/i.test(t))return len?{type:'memo',len}:{type:'memo',len:1048576};if(/^Date and time/i.test(t))return{type:'datetime'};if(/^Whole number/i.test(t))return{type:'int'};if(/^Yes\/No/i.test(t))return{type:'yesno'};if(/^Currency/i.test(t))return{type:'money'};return null;}function psManifest(){var names={runs:TABLE_PROD_NAMES,assets:TABLE_ASSET_NAMES,ms_assets:TABLE_MS_ASSET_NAMES,run_rules:TABLE_RUN_RULE_NAMES,areas:TABLE_AREA_NAMES,sku_master:TABLE_SKU_NAMES,employees:TABLE_EMPLOYEE_NAMES,workshifts:TABLE_WORKSHIFT_NAMES,san_logs:TABLE_LOG_NAMES,cleanplan:TABLE_CLEAN_NAMES,inbox:TABLE_INBOX_NAMES,p_plan:TABLE_P_PLAN_NAMES};var logical=n=>{var m=/^_(.+)_value$/.exec(n);return m?m[1]:n;};var tables=COLUMN_GUIDE.map(t=>{var cols=[],opt=[];t.cols.forEach(c=>{var n=logical(c.name);if(cols.indexOf(n)<0)cols.push(n);if(c.need!=='required'&&opt.indexOf(n)<0)opt.push(n);});var out={t:t.table,names:names[t.key]||[t.table],read:cols,write:PS_WRITES[t.key]?cols:[],opt};var b=PS_BUILD[t.key];if(b){var types={};t.cols.forEach(c=>{var n=logical(c.name),ty=psColType(c.type);if(ty&&!/primary/i.test(c.type)&&(!b.only||b.only.indexOf(n)>=0))types[n]=Object.assign({label:c.label},/guids?$/.test(n)&&ty.type==='text'?{type:'guid'}:ty);});out.cols=types;if(b.primary){out.label=t.displayName;out.owner='org';out.primary=b.primary;}if(b.prompt)out.prompt=b.prompt;}return out;});tables.push({t:TABLE_LINEPRIO,names:TABLE_LINEPRIO_NAMES,read:['craa5_linecode','craa5_name','craa5_linepriority1','craa5_priority','craa5_aliases','craa5_otherspellings'],write:[],opt:['craa5_linecode','craa5_linepriority1','craa5_aliases','craa5_otherspellings']});tables.push({t:HUB_CONFIG_TABLES[0],names:HUB_CONFIG_TABLES,read:['craa5_configkey','craa5_configjson','craa5_savedby','craa5_savedon','craa5_version'],write:['craa5_configkey','craa5_configjson','craa5_savedby','craa5_savedon','craa5_version'],opt:['craa5_savedby','craa5_savedon','craa5_version']});return{appId:'prodsched',app:'Production Scheduler',version:PS_VERSION,tables,config:[]};}var HOST_WEB_API=null;function safeGetXrm(){if(typeof window!=='undefined'){if(window.Xrm&&window.Xrm.WebApi)return hubDiversionWrapXrm(window.Xrm,'prodsched');try{if(window.parent&&window.parent!==window&&window.Xrm&&window.Xrm.WebApi)return hubDiversionWrapXrm(window.Xrm,'prodsched');}catch(e){}try{if(window.top&&window.top!==window&&window.Xrm&&window.Xrm.WebApi)return hubDiversionWrapXrm(window.Xrm,'prodsched');}catch(e){}}if(HOST_WEB_API)return{WebApi:hubDiversionWrapWebApi(HOST_WEB_API,'prodsched')};return null;}var isoZ=ms=>new Date(ms).toISOString().replace(/\.\d{3}Z$/,'Z');var odataStr=s=>String(s).replace(/'/g,"''");var withTimeout=(promise,ms,label)=>new Promise((resolve,reject)=>{var t=setTimeout(()=>reject(new Error(`${label} timed out`)),ms);promise.then(v=>{clearTimeout(t);resolve(v);},e=>{clearTimeout(t);reject(e);});});// Reads rows. Returns an array, or null when EVERY attempt failed (a failed read is never mistaken for "no data").
